INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish7', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":14,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig for en voksen person, der kan være far eller onkel?","o":["mand","mann","mandt","mannd"],"a":"mand","r":"Ordet skrives med ét n og et stumt d til sidst. Ordet 'man' uden d betyder noget andet."},
{"l":32,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find navneordet i sætningen: 'Den lille kat sover nu.'","o":["sover","kat","lille","nu"],"a":"kat","r":"Et navneord er en ting, et dyr eller en person. Du kan sige 'en kat', og det kan du ikke med de andre ord."},
{"l":56,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Efter skole er jeg sulten og vil have noget ___.'","o":["madd","maad","mad","mae"],"a":"mad","r":"Ordet har blødt d til sidst. Det skrives med ét a og ét d."},
{"l":72,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ko, gris og får lever på gården. Hvilket fælles ord passer?","o":["insekter","fisk","fugle","husdyr"],"a":"husdyr","r":"Dyr, som mennesker holder og passer, kalder man husdyr. Køer, grise og får er pattedyr, ikke fugle eller fisk."},
{"l":94,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Døren står åben. Hvilket ord er det modsatte af 'åben'?","o":["lukket","høj","tung","gammel"],"a":"lukket","r":"En dør kan enten være åben eller lukket. De to ord er hinandens modsætninger."},
{"l":110,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket dyr passer efter 'et': 'Vi så et ___ i skoven.'","o":["ræv","egern","hjort","ugle"],"a":"egern","r":"Det hedder et egern. De andre dyr hedder en: en ræv, en hjort, en ugle."},
{"l":132,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Mælk, vand og saft kan man have i et glas. Hvad er de alle sammen?","o":["grøntsager","møbler","drikkevarer","køretøjer"],"a":"drikkevarer","r":"Noget, man kan drikke, kalder man drikkevarer. Ordet fortæller selv, hvad det er."},
{"l":154,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Elevatoren kører op. Hvilket ord er det modsatte af 'op'?","o":["ind","hen","ud","ned"],"a":"ned","r":"Op og ned er modsætninger. 'Ind' er det modsatte af 'ud', så det passer ikke her."},
{"l":172,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Min lillebror er en glad ___ på otte år.'","o":["dreng","drenk","dræng","drengg"],"a":"dreng","r":"Lyden til sidst skrives ng. Med nk ville man høre et k."},
{"l":192,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Gulerod, kartoffel og ært dyrkes i jorden. Hvad er de alle sammen?","o":["drikkevarer","grøntsager","slik","møbler"],"a":"grøntsager","r":"Gulerødder, kartofler og ærter er planter, vi spiser, og vi kalder dem grøntsager."},
{"l":214,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af at være sulten?","o":["tørstig","træt","mæt","syg"],"a":"mæt","r":"Når man har spist nok, er man mæt og ikke sulten længere."},
{"l":231,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vi spiser ved det i køkkenet. Hvordan staves det?","o":["borrd","boord","bordt","bord"],"a":"bord","r":"Ordet ender på et stumt d efter r. Det samme ser du i 'jord' og 'nord'."},
{"l":252,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om regnen skal slutte med punktum?","o":["Det regner i dag","Regner det i dag","Hvornår stopper regnen","Hvorfor regner det"],"a":"Det regner i dag","r":"Den sætning fortæller noget. I de tre andre spørger man om noget, så de skal have spørgsmålstegn."},
{"l":274,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man søsteren til din mor?","o":["faster","moster","kusine","niece"],"a":"moster","r":"Moster kommer af 'mors søster'. Din fars søster hedder din faster."},
{"l":292,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Oskar står derude. Vælg det rigtige ord: 'Jeg vinker til ___.'","o":["han","hans","ham","hun"],"a":"ham","r":"Efter 'til' skal der stå 'ham'. 'Han' bruger man, når Oskar selv gør noget."},
{"l":314,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Dyret svømmer i vandet og har finner. Hvilken stavemåde er rigtig?","o":["fissk","fesk","fisg","fisk"],"a":"fisk","r":"Ordet ender på sk, og der skal kun ét s."},
{"l":331,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form har navneordet 'bogen'?","o":["bestemt ental","ubestemt ental","bestemt flertal","ubestemt flertal"],"a":"bestemt ental","r":"Der er kun én bog, og endelsen -en viser, at det er en bestemt bog."},
{"l":352,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Selma kan ikke sove. Vinden hyler, og grenene slår mod ruden. Hun trækker dynen op over hovedet.' Hvorfor kan Selma ikke sove?","o":["Fordi hun er sulten","Fordi stormen larmer udenfor","Fordi hun har sovet til middag","Fordi hendes dyne er for varm"],"a":"Fordi stormen larmer udenfor","r":"Vinden hyler, og grenene slår mod ruden. Lydene fra uvejret holder hende vågen."},
{"l":372,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange punktummer skal der stå i teksten: 'Jeg er ni år Jeg har en hamster'?","o":["ét","tre","to","fire"],"a":"to","r":"Teksten består af to sætninger. Hver sætning skal slutte med et punktum."},
{"l":394,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan man bruge i stedet for 'vred'?","o":["rolig","venlig","tavs","sur"],"a":"sur","r":"Når man er vred, er man sur på nogen. Rolig og venlig er næsten det modsatte."},
{"l":413,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mira har en fisk i et akvarium. Hun fodrer den hver morgen. Om lørdagen gør far akvariet rent.' Hvem gør akvariet rent?","o":["Miras far","Mira","Miras mor","Miras lærer"],"a":"Miras far","r":"Sidste sætning siger, at far gør akvariet rent. Mira fodrer fisken."},
{"l":432,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Eg, bøg og birk vokser i den danske skov. Hvad er de alle sammen?","o":["blomster","træer","bær","svampe"],"a":"træer","r":"Eg, bøg og birk er navne på træer. Bøgen er et af de mest kendte træer i Danmark."},
{"l":454,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man pelsen fra et får, når den er klippet af?","o":["læder","silke","uld","bomuld"],"a":"uld","r":"Uld kommer fra får og bruges til varmt tøj. Bomuld kommer fra en plante."},
{"l":472,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Du må gerne komme med, ___ du har lyst.'","o":["vis","hviss","viss","hvis"],"a":"hvis","r":"Her skal der stå ordet med stumt h, fordi det betyder 'i det tilfælde at'. Ordet 'vis' betyder klog eller 'at vise'."},
{"l":492,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Asta jubler højt efter kampen: 'Vi vandt'. Hvilket tegn viser, at hun jubler?","o":["udråbstegn","punktum","komma","kolon"],"a":"udråbstegn","r":"Asta siger det med stor glæde og kraft. Det viser man med et udråbstegn."},
{"l":514,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En ung hund kaldes en ___. Hvordan staves det?","o":["valp","hvalp","hvalb","hvallp"],"a":"hvalp","r":"Ordet begynder med stumt h og slutter på lp."},
{"l":531,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: '___ har du det i dag?'","o":["vordan","hvordann","hvordan","hvurdan"],"a":"hvordan","r":"Spørgeordet begynder med stumt h og skrives med o, selvom det kan lyde som å."},
{"l":552,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en regnbue?","o":["en lang bro over en flod","en høj port ved et slot","en stor sky med torden","en bue af farver på himlen"],"a":"en bue af farver på himlen","r":"En regnbue kan man se, når solen skinner, mens det regner. Lyset deler sig i mange farver."},
{"l":572,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er stavet rigtigt: 'Du skal ___ på døren, før du går ind.'","o":["banke","bangke","bancke","bankke"],"a":"banke","r":"Her høres et k efter n, så der skrives nk. Der skal ikke g med."},
{"l":591,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'I morges ___ jeg havregryn.'","o":["spiser","spiste","spise","spist"],"a":"spiste","r":"'I morges' er sket, så ordet skal stå i datid: spiste."},
{"l":612,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'På skolens loppemarked solgte 3.a gamle bøger. Pengene skulle bruges til en tur i zoologisk have.' Hvad skulle pengene bruges til?","o":["Nye bøger til klassen","En ny bold","En tur i zoologisk have","En fest i klassen"],"a":"En tur i zoologisk have","r":"Den sidste sætning fortæller, at pengene skulle bruges til en tur i zoologisk have."},
{"l":631,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du har den på foden inden i skoen. Hvilket ord er stavet rigtigt?","o":["strømbe","strømppe","strøme","strømpe"],"a":"strømpe","r":"Efter m kommer et p, og det skrives kun én gang."},
{"l":655,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solen var ved at gå ned. Lars tog sin bold under armen og begyndte at gå hjem. Mor havde sagt, at han skulle være hjemme til aftensmad.' Hvad tid på dagen er det?","o":["Sidst på eftermiddagen","Tidlig morgen","Midt på dagen","Midt om natten"],"a":"Sidst på eftermiddagen","r":"Solen går ned, og det er snart tid til aftensmad. Det passer med sidst på eftermiddagen."},
{"l":672,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad skriver man i en dagbog?","o":["hvad varerne koster i butikken","hvad man har oplevet og tænkt","hvad der står i avisen i dag","hvad regnestykkerne giver i matematik"],"a":"hvad man har oplevet og tænkt","r":"En dagbog er en bog, hvor man skriver om sine dage. Den er tit hemmelig."},
{"l":690,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I klassen er der fire grupper. Hver gruppe skal lave en plakat om et dyr. Sami og Julie vælger hesten.' Hvad skal Sami og Julie lave?","o":["En tegneserie om en hest","En fortælling om et dyr","En plakat om heste","En bog om hesten"],"a":"En plakat om heste","r":"Hver gruppe skal lave en plakat om et dyr, og de to har valgt hesten."},
{"l":709,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at have 'travlt'?","o":["at have god tid","at have ondt i maven","at være meget træt","at have meget at nå"],"a":"at have meget at nå","r":"Den, der har travlt, skal nå mange ting på kort tid og må skynde sig."},
{"l":732,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'kort' her: 'Vi spiller kort efter aftensmaden.'","o":["papirstykker, man spiller med","noget, der ikke tager lang tid","et landkort, man finder vej med","en hilsen, man sender med posten"],"a":"papirstykker, man spiller med","r":"Kort kan betyde mange ting. Når man spiller kort, bruger man et sæt spillekort."},
{"l":751,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Yasmin kom ind i klassen, råbte alle tillykke. På hendes bord lå der et kort, som alle havde skrevet på.' Hvad var der sket?","o":["Yasmin havde vundet et løb","Klassen havde sørget for en overraskelse","Læreren var blevet gift","Yasmin var flyttet til en ny klasse"],"a":"Klassen havde sørget for en overraskelse","r":"Alle råbte på samme tid og havde skrevet på et kort. De havde planlagt det for at glæde Yasmin."},
{"l":772,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Dagen efter fredag. Hvordan staves den?","o":["lødag","lørdaw","lørdag","lørrdag"],"a":"lørdag","r":"Der står ét r, selvom det er svagt. Slutningen er -dag."},
{"l":792,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord bruger man, når man vil fortælle, hvor høj en ting er?","o":["vægt","farve","alder","højde"],"a":"højde","r":"Højde kommer af 'høj'. Vægt fortæller, hvor tung en ting er."},
{"l":811,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klara skulle sove hos sin veninde for første gang. Da det blev mørkt, begyndte hun at tænke på sin egen seng og sin mor.' Hvordan havde Klara det?","o":["Hun havde hjemve","Hun var sulten","Hun var vred","Hun var syg"],"a":"Hun havde hjemve","r":"Hun tænker på sin egen seng og sin mor. Det er det, man kalder at have hjemve."},
{"l":829,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassen plantede et træ i skolegården. Hver uge vander to elever træet. I år er det Sofus og Nour, der har den første uge.' Hvad skal Sofus og Nour gøre?","o":["Plante et nyt træ","Vande træet","Klippe træet","Rydde gården"],"a":"Vande træet","r":"To elever vander træet hver uge, og Sofus og Nour har den første uge."},
{"l":852,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Min fætter bor i sverige og taler svensk.'?","o":["fætter","taler","sverige","svensk"],"a":"sverige","r":"Sverige er navnet på et land. Sprog som svensk skrives med lille, selv om det ligner landets navn."},
{"l":872,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Bussen ___ om fem minutter.'","o":["komme","komer","kåmmer","kommer"],"a":"kommer","r":"O'et er kort, så der skal to m'er. Nutid ender på -r."},
{"l":889,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hanna ville gerne være med til at spille kort. Men reglerne var svære. Så hun satte sig ved siden af Mustafa og så på, hvordan han gjorde.' Hvorfor sad Hanna ved siden af Mustafa?","o":["For at lære spillet","For at snyde ham","For at tale med ham","For at holde hans kort"],"a":"For at lære spillet","r":"Hun synes, reglerne var svære, så hun ser, hvordan han spiller, for at lære det."},
{"l":912,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'tilfreds'?","o":["træt","fornøjet","nervøs","nysgerrig"],"a":"fornøjet","r":"Den, der er tilfreds eller fornøjet, er glad for det, der er sket."},
{"l":931,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Jeg ___ dynen på sengen hver morgen.'","o":["ligger","lægge","lægger","læger"],"a":"lægger","r":"Nogen gør noget ved dynen, så her skal 'lægger' stå. Læger er personer, der hjælper syge."},
{"l":950,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det havde regnet i tre dage. Vandet i åen steg og steg. Til sidst løb det ind over stien, og Noor måtte tage en anden vej hjem.' Hvorfor måtte Noor tage en anden vej?","o":["Hun ville gå en længere tur","Stien var spærret af et træ","Hun skulle hente sin bror","Stien stod under vand"],"a":"Stien stod under vand","r":"Der havde regnet så meget, at åen løb ind over stien. Så kunne hun ikke gå dér."},
{"l":972,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et fyrtårn?","o":["et tårn med lys, der viser skibe vej","et tårn, hvor brandfolk øver sig","et tårn, hvor man opbevarer brænde","et tårn med klokker, der ringer"],"a":"et tårn med lys, der viser skibe vej","r":"Et fyrtårn står ved kysten. Lyset fortæller skibene, hvor land og farlige steder er."},
{"l":993,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solen var lige gået ned, da flagermusene kom frem. De fløj lavt over søen og fangede insekter. Ved daggry hang de igen i det gamle træ.' Hvornår er flagermusene ude?","o":["Hele dagen","Om natten","Kun om morgenen","Om middagen"],"a":"Om natten","r":"De kommer frem efter solnedgang og er tilbage ved daggry. Det er natten."},
{"l":1011,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da læreren sagde, at de skulle arbejde to og to, kiggede Mads straks på Sami. Sami nikkede. Sådan havde det været siden børnehaven.' Hvad forstår man om Mads og Sami?","o":["De er uvenner","De er nye i klassen","De er bedste venner","De kender ikke hinanden"],"a":"De er bedste venner","r":"De vælger hinanden uden at sige noget og har gjort det siden børnehaven. Det gør man med sin bedste ven."},
{"l":1031,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord passer: 'Hun hjælper altid andre og er en ___ pige.'","o":["vennlig","venli","vendlig","venlig"],"a":"venlig","r":"Ordet kommer af 'ven', så der er ét n. Det ender på -lig."},
{"l":1047,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Efter den lange tur er jeg meget ___.'","o":["træt","tret","trætt","trat"],"a":"træt","r":"Ordet skrives med æ og ét t til sidst, selvom vokalen er kort."},
{"l":1071,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nu havde Ingrid prøvet tre gange at hoppe over bukken, og hver gang stoppede hun lige foran den. Fjerde gang satte hun farten op og klarede den.' Hvad betyder 'satte farten op'?","o":["Gik langsommere","Løb hurtigere","Stoppede helt","Hoppede til siden"],"a":"Løb hurtigere","r":"At sætte farten op er at bevæge sig hurtigere. Med mere fart kunne hun klare bukken."},
{"l":1090,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes det, man skal lære af en fabel?","o":["et rim","en titel","en moral","et kapitel"],"a":"en moral","r":"En fabel er en kort historie, der vil lære os noget. Det, den vil lære os, kaldes moralen."},
{"l":1111,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Danmark er et egennavn. Hvilket fællesnavn passer til det?","o":["by","ø","sø","land"],"a":"land","r":"Fællesnavnet siger, hvad slags sted det er. Danmark er et land, ligesom Norge og Sverige."},
{"l":1131,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Stedet med gynger og rutsjebane. Hvordan staves det?","o":["legeplads","legeplas","lege plads","legeblads"],"a":"legeplads","r":"Sammensatte ord skrives i ét ord. Husk det stumme d i 'plads'."},
{"l":1150,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form passer: 'Da vi kom hjem, ___ hunden i sin kurv.'","o":["ligger","lå","ligge","ligget"],"a":"lå","r":"'Kom' viser, at det er fortid. Datid af 'at ligge' er 'lå'."},
{"l":1167,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Yusuf vil ikke ændre mening, selv om alle siger, at han tager fejl. Hvordan er han?","o":["høflig","forsigtig","stædig","gavmild"],"a":"stædig","r":"Den, der er stædig, holder fast i sin mening og giver sig ikke, heller ikke når andre beder om det."},
{"l":1189,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at være 'beskeden'?","o":["at man altid vil være den bedste","at man ikke gider hjælpe andre","at man tit glemmer sine ting","at man ikke praler med det, man kan"],"a":"at man ikke praler med det, man kan","r":"En beskeden person gør ikke meget ud af sig selv, selv om vedkommende er dygtig."},
{"l":1212,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Amina har 'ansvar' for kaninen. Hvad betyder det?","o":["at hun skal sørge for, at den har det godt","at hun kun må lege med den om søndagen","at hun skal sælge den til en af naboerne","at hun skal holde sig langt væk fra den"],"a":"at hun skal sørge for, at den har det godt","r":"Den, der har ansvar for noget, skal passe på det. Amina skal altså give kaninen mad og vand."},
{"l":1231,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den orange frugt med tyk skræl og saftige både. Hvordan staves den?","o":["apelsin","appelsin","appelsien","abbelsin"],"a":"appelsin","r":"Ordet har to p'er efter a og slutter på -sin."},
{"l":1249,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en, der mumler?","o":["synger højt og klart","råber vredt og længe","taler lavt og utydeligt","græder stille og længe"],"a":"taler lavt og utydeligt","r":"Den, der mumler, taler næsten ind i sig selv, så det er svært at høre, hvad der bliver sagt."},
{"l":1271,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Natten efter stormen var der ingen strøm i hele byen. Køleskabene blev varme, og folk gik med lommelygter. Mange tændte stearinlys, og naboer, som aldrig før havde talt sammen, hjalp hinanden.' Hvad skete der med naboerne?","o":["De blev uvenner over strømmen","De flyttede væk fra byen","De købte nye køleskabe","De kom til at tale sammen"],"a":"De kom til at tale sammen","r":"Teksten siger, at naboer, der aldrig havde talt sammen, nu hjalp hinanden. Stormen bragte dem sammen."},
{"l":1289,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Der stod tre ___ ved busstoppestedet.'","o":["mænd","mænder","mend","mander"],"a":"mænd","r":"Flertal af 'mand' skifter vokal til æ og får ingen endelse."},
{"l":1309,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder ordsproget 'Bedre en fugl i hånden end ti på taget'?","o":["at det er bedre at have en fugl end at have ti katte i huset","at lidt, man har sikkert, er bedre end meget, man håber på","at fugle på taget laver mere larm, end fugle i et bur gør","at man skal passe på med at klatre op på høje tage for fugle"],"a":"at lidt, man har sikkert, er bedre end meget, man håber på","r":"Fuglen i hånden har man allerede. De ti på taget kan flyve væk når som helst."},
{"l":1331,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Min storesøster er tre år ___ end mig.'","o":["æller","eldre","ældre","ældere"],"a":"ældre","r":"Ordet begynder med æ og skrives med d og r efter hinanden."},
{"l":1349,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I dag har eleverne ingen skoletasker med, kun madpakker og gode sko. Læreren deler kort og kompas ud. Klokken ni går klassen ud ad lågen.' Hvad skal klassen nok?","o":["Have matematik i klassen","Spise i kantinen","Have besøg af en forfatter","På tur i naturen"],"a":"På tur i naturen","r":"Gode sko, kort og kompas bruger man på tur, og klassen går ud ad lågen. Så skal de ikke have almindelige timer."},
{"l":1371,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvor mange udsagnsord er der i sætningen: 'Hun løb hjem og spiste en bolle.'","o":["to","ét","tre","fire"],"a":"to","r":"Udsagnsordene er 'løb' og 'spiste'. Begge fortæller, hvad hun gjorde."},
{"l":1392,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Politiet ville ___ sagen og finde ud af, hvad der var sket.'","o":["fortryde","undersøge","pynte","beundre"],"a":"undersøge","r":"At undersøge er at se grundigt på noget for at finde ud af sandheden."},
{"l":1409,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jonathan ser på tavlen, så på sit hæfte og så over på sidemandens hæfte. Han holder blyanten stille og tygger på sin læbe.' Hvad er der nok galt?","o":["Han har mistet sin blyant","Han er sur på sin sidemand","Han kan ikke løse opgaven","Han er færdig før alle andre"],"a":"Han kan ikke løse opgaven","r":"Han kigger efter hjælp og skriver ikke noget. Blyanten har han i hånden, så han sidder fast i opgaven."},
{"l":1430,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'tit'?","o":["sjældent","aldrig","snart","ofte"],"a":"ofte","r":"'Tit' og 'ofte' betyder begge, at noget sker mange gange. 'Sjældent' er næsten det modsatte."},
{"l":1449,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Salma og Noa havde aftalt at mødes ved springvandet klokken tre. Klokken halv fire stod Salma der stadig alene. Hun tog sin telefon frem og skrev en besked.' Hvad vil Salma nok spørge Noa om?","o":["Hvor Noa bliver af","Hvad klokken er","Hvor springvandet ligger","Hvad de skal have at spise"],"a":"Hvor Noa bliver af","r":"Salma har ventet en halv time, og Noa er ikke kommet. Hun står selv ved springvandet og har uret på telefonen."},
{"l":1468,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af at 'købe' noget?","o":["at betale det","at sælge det","at låne det","at bytte det"],"a":"at sælge det","r":"Den, der køber, får varen, og den, der sælger, giver den fra sig. Man betaler, når man køber, så 'betale' er ikke det modsatte."},
{"l":1490,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En skarp, stærkt duftende plante med små fed, som bruges i maden. Find den rigtige stavemåde.","o":["vidløg","hvidlød","hvidløg","hvidlog"],"a":"hvidløg","r":"Ordet består af 'hvid' og 'løg'. Begge dele skal staves, som de plejer."},
{"l":1509,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Efter løbeturen skal du ___ dig lidt.'","o":["vile","hville","hvilæ","hvile"],"a":"hvile","r":"Ordet begynder med hv. I'et er langt, så der er ét l."},
{"l":1529,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad laver en pedel på en skole?","o":["passer bygningen og reparerer ting","underviser klassen i matematik","laver mad til alle eleverne","kører eleverne til skole i bus"],"a":"passer bygningen og reparerer ting","r":"Pedellen sørger for, at skolens bygninger virker. Det er lærerne, der underviser."},
{"l":1549,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'Mine nye ___ er allerede snavsede.'","o":["skoen","sko","skoene","skoens"],"a":"sko","r":"Ordet 'sko' får ingen endelse i ubestemt flertal: en sko, to sko. Efter 'mine nye' står den ubestemte form."},
{"l":1566,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Mia siger noget forkert højt i klassen, og alle kigger på hende. Hun bliver rød i kinderne. Hvordan har hun det?","o":["Hun er stolt.","Hun er tørstig.","Hun er flov.","Hun er modig."],"a":"Hun er flov.","r":"Man bliver flov, når man synes, at man har dummet sig foran andre. Røde kinder er et typisk tegn."},
{"l":1589,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord dækker både 'hammer', 'sav' og 'skruetrækker'?","o":["legetøj","tøj","møbler","værktøj"],"a":"værktøj","r":"'Værktøj' er det fælles ord for redskaber, man bygger og reparerer med."},
{"l":1610,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Kom, lad os gå en tur i skoven, / solen skinner højt deroven.' Hvilke to ord rimer?","o":["skoven og deroven","tur og skoven","solen og højt","gå og skinner"],"a":"skoven og deroven","r":"Skoven og deroven slutter på den samme lyd. Her står rimene sidst i linjerne, som de tit gør i et vers."},
{"l":1629,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Liv var ikke bange for at sige sin mening. Men da hendes bedste veninde spurgte, om det nye hår var pænt, kiggede Liv ned og sagde: Det er da meget nyt.' Hvad synes Liv nok om håret?","o":["At det er meget pænt","At det ikke er pænt","At hun selv vil have det","At det er meget dyrt"],"a":"At det ikke er pænt","r":"Hun plejer at sige sin mening. At hun undgår spørgsmålet, viser, at hun ikke vil såre sin veninde. Hun synes ikke, det er pænt."},
{"l":1650,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvem er 'uheldig'?","o":["en, der altid vinder i spil","en, der er meget stærk","en, der ikke har held med sig","en, der tit er glad"],"a":"en, der ikke har held med sig","r":"Forstavelsen u- vender betydningen om, så 'uheldig' er det modsatte af 'heldig'."},
{"l":1670,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du sender det med posten. Hvilket ord er stavet rigtigt?","o":["bræv","brew","bref","brev"],"a":"brev","r":"Ordet skrives med e og ender på v, selvom det lyder som u."},
{"l":1689,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den del af trøjen, som armen sidder i. Hvordan staves den?","o":["ærme","erme","ærmme","ærmæ"],"a":"ærme","r":"Ordet begynder med æ og har ét m. Det slutter på e."},
{"l":1710,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solen er en stjerne. Den ser større ud end de andre stjerner, fordi den er meget tættere på os. Mange af de små stjerner på himlen er faktisk større end solen.' Hvorfor ser solen så stor ud?","o":["Fordi den er verdens største stjerne","Fordi den er tættere på os","Fordi den skinner om dagen","Fordi den er varmere end andre"],"a":"Fordi den er tættere på os","r":"Teksten forklarer, at det er afstanden, der gør det. Solen er ikke den største stjerne, for mange er større."},
{"l":1729,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er datid af 'at have': 'Sidste år ___ jeg lange fletninger.'","o":["har","have","havde","haft"],"a":"havde","r":"'Sidste år' kræver datid: havde. 'Haft' står efter 'har'."},
{"l":1746,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Selma ville gerne have en hund. Hun lovede at gå tur hver dag, også i regn. Hendes far sagde ikke nej, men bad hende om at passe naboens hund i en uge først.' Hvorfor skal Selma nok passe naboens hund?","o":["Fordi naboen skal på ferie","Fordi far er allergisk over for hunde","For at tjene penge til sin egen hund","For at se, om hun kan klare ansvaret"],"a":"For at se, om hun kan klare ansvaret","r":"Far siger 'først'. Hun skal vise, at hun holder sit løfte, før hun kan få sin egen hund."},
{"l":1769,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'bæk'?","o":["et lille vandløb","en lille skov","en lille bakke","en lille mark"],"a":"et lille vandløb","r":"En bæk er et smalt vandløb. Flere bække kan løbe sammen og blive til en å."},
{"l":1790,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvor mange hunde møder soldaten i H.C. Andersens 'Fyrtøjet'?","o":["to","tre","fire","syv"],"a":"tre","r":"Der er tre hunde med store øjne, og de vogter kobber, sølv og guld. Tretallet går igen i mange eventyr."},
{"l":1809,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Moster Bente kom altid for sent. Da hun skulle med toget, sagde mor, at toget gik en halv time tidligere, end det gjorde.' Hvorfor sagde mor det?","o":["Fordi hun havde læst forkert","Fordi toget var blevet flyttet","For at Bente skulle nå toget","For at Bente skulle blive sur"],"a":"For at Bente skulle nå toget","r":"Bente kommer altid for sent. Hvis hun tror, toget går før, når hun det alligevel til tiden."},
{"l":1829,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvornår er man 'ensom'?","o":["Når man er den eneste, der har vundet.","Når man har mange venner omkring sig.","Når man ikke er sulten om morgenen.","Når man savner nogen at være sammen med."],"a":"Når man savner nogen at være sammen med.","r":"Ensomhed er en trist følelse af ikke at have nogen. Det er ikke det samme som at have lyst til at være lidt for sig selv."},
{"l":1850,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilket dyr redder Tommelise, så hun slipper for at blive gift med muldvarpen?","o":["svalen","tudsen","markmusen","oldenborren"],"a":"svalen","r":"Tommelise har passet den syge svale. Til tak flyver den hende væk til de varme lande."},
{"l":1870,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Jeg ___ en hund i fødselsdagsgave.'","o":["fikk","fik","fick","figk"],"a":"fik","r":"Datid af 'få' skrives med ét k, ligesom 'gik'."},
{"l":1889,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord passer: 'Hun ___ sit navn på tavlen i går.'","o":["skreu","skrew","skrev","skreev"],"a":"skrev","r":"Datid af 'skrive' skrives med e og ender på v."},
{"l":1909,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Vi skal bruge ___ stole end i går.'","o":["mere","mest","meget","flere"],"a":"flere","r":"Stole kan tælles, så det hedder 'flere'. 'Mere' bruger man om noget, der ikke kan tælles."},
{"l":1927,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Nilen i Afrika er en lang ___.'","o":["flod","flodd","flood","flåd"],"a":"flod","r":"Ordet ender på blødt d. Vokalen skrives med ét o."},
{"l":1949,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord er lavet af tillægsordet 'kold'?","o":["kuld","kulde","kule","kurv"],"a":"kulde","r":"Når det er koldt, taler vi om kulde. Et kuld er derimod de unger, et dyr får på én gang."},
{"l":1969,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Bøj tillægsordet rigtigt: 'Det var et ___ svar.'","o":["venlig","venlige","venligt","venlighed"],"a":"venligt","r":"Det hedder et svar, så tillægsordet får -t: et venligt svar."},
{"l":1986,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Til fastelavn var alle klædt ud. Der var pirater, løver og prinsesser. Men Mads havde pakket sig ind i toiletpapir, og det gik langsomt op, når han løb.' Hvad er Mads nok klædt ud som?","o":["En løve","En pirat","En prins","En mumie"],"a":"En mumie","r":"En, der er pakket ind i strimler, ligner en mumie. Løver og pirater har ikke strimler om kroppen."},
{"l":2010,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'ryddelig', når vi taler om et værelse?","o":["rodet","lille","mørk","stille"],"a":"rodet","r":"I et ryddeligt værelse ligger tingene på plads, og i et rodet værelse ligger de hulter til bulter."},
{"l":2029,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Er det ___ penalhus, Yasmin?'","o":["din","dit","dine","dig"],"a":"dit","r":"Det hedder et penalhus, så stedordet skal være 'dit'."},
{"l":2049,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da læreren kom ind, stoppede snakken. Alle kiggede ned i deres bøger, men Nikolaj havde en plet af tavlekridt på næsen, og der stod en sjov tegning på tavlen.' Hvad har Nikolaj nok lavet?","o":["Han har gjort tavlen ren","Han har læst i sin bog","Han har tegnet på tavlen","Han har spist kridt"],"a":"Han har tegnet på tavlen","r":"Kridt på næsen og en sjov tegning på tavlen afslører, hvem der har tegnet."},
{"l":2069,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Må jeg ___ dig om noget?'","o":["spørger","spørre","spøre","spørge"],"a":"spørge","r":"Efter 'må' står navneform. Ordet skrives med rg, selvom g'et næsten ikke høres."},
{"l":2088,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige datidsform: 'Far ___ is til os i går.'","o":["købte","købde","kobte","køpte"],"a":"købte","r":"Datid af 'købe' beholder b'et og får -te. Der skal ikke p med."},
{"l":2107,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Frøen ___ ned i søen.'","o":["hopede","hoppede","hoppete","hoppedde"],"a":"hoppede","r":"Datid af 'hoppe' ender på -ede. Der skal to p'er, fordi o'et er kort."},
{"l":2130,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad sker der med en blomst, der 'visner'?","o":["Den får flere knopper.","Den vokser sig større.","Den tørrer ud og dør.","Den dufter stærkere."],"a":"Den tørrer ud og dør.","r":"En blomst visner, når den ikke får vand nok, eller når den bliver gammel."},
{"l":2148,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange tror, at tyre bliver vrede af farven rød. Men tyre kan slet ikke se rød farve særlig godt. Det er kappens bevægelser, der får dem til at løbe frem.' Hvilken misforståelse vil teksten rette?","o":["At tyre ikke kan se","At tyre kan lide kapper","At tyre løber meget hurtigt","At farven rød gør tyre vrede"],"a":"At farven rød gør tyre vrede","r":"Teksten starter med noget, 'mange tror', og forklarer så, at det ikke passer. Det er bevægelsen, der gør det."},
{"l":2168,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sæt ordet ind: 'Da ballonen pludselig sprang, blev Noor ___ og hoppede højt.'","o":["forskrækket","forelsket","forkølet","forsinket"],"a":"forskrækket","r":"Man bliver forskrækket af noget, der pludselig sker. Alle ordene begynder med for-, men kun dette ene passer til knaldet."},
{"l":2190,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes ord som 'BANG', 'KLONK' og 'SPLASH' i en tegneserie?","o":["navneord","lydord","tillægsord","stedord"],"a":"lydord","r":"Lydord efterligner en lyd. I tegneserier gør de, at man næsten kan høre, hvad der sker."},
{"l":2209,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er bindeord: 'Vi blev hjemme, fordi Bo var syg.'","o":["hjemme","syg","fordi","blev"],"a":"fordi","r":"'Fordi' binder de to sætninger sammen og fortæller årsagen."},
{"l":2229,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nogle mener, at eleverne skal have mobilfri skole. De siger, at man så leger mere i pausen. Andre siger, at man skal lære at styre sin telefon selv. Der er ikke noget enkelt svar.' Hvad gør teksten?","o":["Siger, at mobiler er farlige","Beviser, at eleverne leger mere","Forklarer, hvordan en telefon virker","Viser to forskellige holdninger"],"a":"Viser to forskellige holdninger","r":"Teksten viser, at nogle mener én ting, og andre mener noget andet, uden at vælge side."},
{"l":2250,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige flertalsform: 'I kurven ligger der fem røde ___.'","o":["æbler","æbeler","æbleer","æbbler"],"a":"æbler","r":"Flertal får -r efter e'et, og der er ét b."},
{"l":2269,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find grundleddet, selv om det ikke står først: 'I går købte mor en ny cykel.'","o":["købte","mor","I går","en ny cykel"],"a":"mor","r":"Spørg: Hvem købte? Det gjorde mor. 'I går' står først, men fortæller kun hvornår."},
{"l":2288,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Din fars mor. Hvordan staves det?","o":["bestemor","bedstemoer","bedstemor","bedsdemor"],"a":"bedstemor","r":"Ordet består af 'bedste' og 'mor'. Det stumme d skal med."},
{"l":2307,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det røde køretøj med lang stige og slanger. Hvordan staves det?","o":["branbil","brandbill","brand bil","brandbil"],"a":"brandbil","r":"Ordet består af 'brand' og 'bil'. Det skrives i ét ord, og d'et skal med."},
{"l":2328,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mika havde ledt overalt efter sin madkasse. Ingrid fandt den ude på gangen og stillede den på hans bord, mens ingen så det. Da Mika blev glad, sagde Ingrid ingenting, men hun smilede for sig selv.' Hvorfor smilede Ingrid?","o":["Hun var glad for at have hjulpet ham","Hun ville drille Mika lidt","Hun havde spist hans madpakke","Hun skulle snart have frikvarter"],"a":"Hun var glad for at have hjulpet ham","r":"Hun hjalp Mika uden at sige det til nogen. Smilet kommer, da hun ser, at han bliver glad."},
{"l":2347,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'pligt'?","o":["noget, man drømmer om","noget, man skal gøre","noget, man får i gave","noget, man har lov til"],"a":"noget, man skal gøre","r":"En pligt er noget, man er nødt til, selvom man måske ikke har lyst. Noget, man har lov til, kaldes en ret."},
{"l":2365,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvorfor står der komma i: 'Æbler, pærer og blommer vokser i haven.'?","o":["Fordi nogen siger noget","Fordi sætningen er et spørgsmål","Fordi ordene er en opremsning","Fordi en ledsætning står først"],"a":"Fordi ordene er en opremsning","r":"Tre slags frugt står lige efter hinanden. Sådan en opremsning får komma mellem delene, men ikke foran 'og'."},
{"l":2388,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vinden var stilnet af, og tågen lå tungt over marken. Man kunne knap se til hegnet. Køerne stod som grå skygger og sagde ikke en lyd.' Hvilken stemning giver teksten?","o":["Festlig og larmende","Varm og solrig","Travl og munter","Stille og lidt uhyggelig"],"a":"Stille og lidt uhyggelig","r":"Tåge, grå skygger og ingen lyde giver en stille stemning, som kan virke lidt uhyggelig."},
{"l":2408,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad føler man, når man 'fortryder' noget?","o":["at man ikke skulle have gjort det","at man var dygtig til at gøre det","at man gerne vil gøre det igen","at man har glemt at gøre det"],"a":"at man ikke skulle have gjort det","r":"Den, der fortryder, ville ønske, at man havde handlet anderledes."},
{"l":2425,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor skal anførselstegnene stå, når sætningen slutter med 'sagde Noah'?","o":["»Jeg er træt, sagde Noah«.","»Jeg er træt«, sagde Noah.","Jeg er »træt«, sagde Noah.","»Jeg« er træt, sagde Noah."],"a":"»Jeg er træt«, sagde Noah.","r":"Anførselstegnene står om alle de ord, Noah siger, og slutter før 'sagde Noah'."},
{"l":2449,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'løb' i sætningen: 'Vi løb hele vejen hjem fra stranden.'","o":["navneord","tillægsord","udsagnsord","stedord"],"a":"udsagnsord","r":"Her fortæller 'løb', hvad vi gjorde. Det er datid af 'at løbe'."},
{"l":2468,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad viser en 'fødekæde'?","o":["hvor dyrene bliver født henne","hvor lang tid en unge er om at vokse","hvordan en halskæde bliver lavet","hvem der spiser hvem i naturen"],"a":"hvem der spiser hvem i naturen","r":"En fødekæde kan for eksempel være: græs, hare, ræv. Hvert led er føde for det næste."},
{"l":2487,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Geparden er en meget ___ løber.'","o":["hurtig","hurti","hurrtig","hortig"],"a":"hurtig","r":"Ordet skrives med ét r og slutter på -ig."},
{"l":2506,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Det er en ___ besked, så læs den nu.'","o":["vikti","vigtig","vigti","viktig"],"a":"vigtig","r":"Ordet skrives med gt i midten og slutter på -ig. Der skal ikke k med."},
{"l":2528,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken forstavelse skal foran 'handle', så ordet betyder at behandle nogen meget dårligt?","o":["u-","for-","mis-","be-"],"a":"mis-","r":"At mishandle er at behandle dårligt. Pas på: 'forhandle' og 'behandle' er også ord, men de betyder noget andet."},
{"l":2545,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse er 'mod' i sætningen: 'Bolden trillede mod målet.'","o":["navneord","tillægsord","udsagnsord","forholdsord"],"a":"forholdsord","r":"Her viser 'mod' retningen for bolden i forhold til målet. Så er det et forholdsord."},
{"l":2568,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da klassen havde læst digtet, bad læreren dem om at sige ét ord om det. Sofie sagde ensom, Malthe sagde kold, og Rashid sagde grå. Læreren smilede, for de havde alle fanget det samme.' Hvad havde eleverne fanget?","o":["Digtets stemning","Digtets længde","Digterens navn","Digtets årstal"],"a":"Digtets stemning","r":"Ordene ensom, kold og grå beskriver den samme følelse. Det er digtets stemning."},
{"l":2588,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af at 'forbedre' noget?","o":["at forandre det","at forværre det","at forstærke det","at forklare det"],"a":"at forværre det","r":"Bedre og værre er hinandens modsætninger, og det gælder også her. At forandre noget kan gå begge veje."},
{"l":2605,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tæl udsagnsordene: 'Vi spiste, legede og sov i teltet.'","o":["to","fire","tre","ét"],"a":"tre","r":"'Spiste', 'legede' og 'sov' er alle udsagnsord i datid."},
{"l":2629,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken række passer til sætningen 'Søde børn leger.'?","o":["navneord, tillægsord, udsagnsord","tillægsord, udsagnsord, navneord","stedord, navneord, udsagnsord","tillægsord, navneord, udsagnsord"],"a":"tillægsord, navneord, udsagnsord","r":"'Søde' fortæller, hvordan børnene er, 'børn' er navneordet, og 'leger' er udsagnsordet."},
{"l":2649,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør man, når man 'overdriver'?","o":["Man gør noget større, end det egentlig er.","Man kører bilen alt for hurtigt på vejen.","Man fortæller historien helt præcist.","Man siger slet ikke noget om det."],"a":"Man gør noget større, end det egentlig er.","r":"Hvis du siger, at du har ventet i tusind år, så overdriver du. Ordet har ikke noget at gøre med at køre."},
{"l":2667,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rødkælken synger også om vinteren. Hannen forsvarer nemlig sit område hele året, for der skal være nok mad til den selv. Sangen er altså ikke altid glæde, men også en besked til andre.' Hvad er budskabet i sangen?","o":["Kom og spis med mig","Hold dig væk fra mit område","Jeg er ved at fryse","Her er der en fare"],"a":"Hold dig væk fra mit område","r":"Hannen forsvarer sit område, og sangen er en besked til andre fugle om, at stedet er optaget."},
{"l":2687,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Stedet, hvor du kan låne bøger. Find den rigtige stavemåde.","o":["bibliotæk","biblotek","bibliotek","bibbliotek"],"a":"bibliotek","r":"Ordet skrives med e og ét b i midten. Husk i'et efter l."},
{"l":2709,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad viser man, når man viser 'medfølelse'?","o":["at man gerne vil følges med en anden hjem","at man kan mærke ting med fingrene i mørket","at man er bedre end de andre i klassen","at man forstår, at en anden har det svært"],"a":"at man forstår, at en anden har det svært","r":"Medfølelse betyder at føle med en anden. Ordet har ikke noget at gøre med at følges ad på vejen."},
{"l":2725,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Jakkerne tilhører eleverne. Hvilken form passer: 'Alle ___ jakker hang i gangen.'","o":["elevernes","elever","eleverne","elev"],"a":"elevernes","r":"Jakkerne tilhører eleverne, så navneordet skal have -s: elevernes jakker."},
{"l":2748,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Dagen efter skænderiet lå der en lap papir i Maltes taske. Der stod kun: Fodbold i dag? Han vidste godt, hvem der havde skrevet den. Han smilede og tog sine støvler med.' Hvad betyder sedlen?","o":["At der er en vigtig kamp i dag","At vennen vil være venner igen","At træneren har ændret tiden","At Malte skal købe nye støvler"],"a":"At vennen vil være venner igen","r":"Efter et skænderi er sedlen en stille måde at sige undskyld. Malte smiler og vil gerne med."},
{"l":2770,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at noget er 'uundgåeligt'?","o":["at det er umuligt at gå derhen til fods","at det sker meget sjældent i Danmark","at det vil ske, uanset hvad man gør","at det kan stoppes i tide af en voksen"],"a":"at det vil ske, uanset hvad man gør","r":"Noget uundgåeligt kan man ikke slippe for. Forstavelsen u- siger her, at det ikke kan undgås."},
{"l":2785,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken tekst om Emmas spørgsmål har de rigtige tegn?","o":["Emma spurgte: »Hvem vil med!« Alle råbte: »Det vil jeg?«","Emma spurgte »: Hvem vil med?« Alle råbte »: Det vil jeg!«","Emma spurgte, »Hvem vil med.« Alle råbte, »Det vil jeg.«","Emma spurgte: »Hvem vil med?« Alle råbte: »Det vil jeg!«"],"a":"Emma spurgte: »Hvem vil med?« Alle råbte: »Det vil jeg!«","r":"Begge steder står der kolon før den direkte tale. Emmas spørgsmål får spørgsmålstegn, og råbet får udråbstegn."},
{"l":2809,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er grundleddet: 'Ham kender jeg godt fra skolen.'","o":["jeg","Ham","kender","fra skolen"],"a":"jeg","r":"Spørg: Hvem kender? Det gør jeg. 'Ham' står først, men det er ham, der bliver kendt."},
{"l":2829,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sådan gør du: Læg et blad under papiret, og tegn hen over med en farveblyant. Så kommer bladets årer frem på papiret.' Hvilken slags tekst er det?","o":["En fortælling","En vejledning","En nyhed","Et digt"],"a":"En vejledning","r":"'Sådan gør du' og opfordringer som 'læg' og 'tegn' viser, at det er en vejledning."},
{"l":2848,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Noget, du slet ikke havde ventet, for eksempel en gave uden grund. Hvordan staves det?","o":["overasskelse","overaskelse","overraskelse","overraskelsse"],"a":"overraskelse","r":"Ordet skrives med to r'er i midten: ét i 'over-' og ét i '-raskelse'."},
{"l":2870,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"I eventyr står godt og ondt tydeligt over for hinanden. Hvad sker der som regel med det onde til sidst?","o":["Det vinder og får hele riget","Det bliver gift med helten","Det får lov at fortsætte som før","Det bliver straffet eller besejret"],"a":"Det bliver straffet eller besejret","r":"I eventyr sejrer det gode næsten altid. Derfor må det onde tabe til sidst, så der er orden i verden igen."},
{"l":2889,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Søholm Bibliotek har fået en læsehund. Hunden hedder Balder, og den ligger stille ved siden af børn, der øver sig i at læse højt. Den retter aldrig fejl og griner aldrig. Derfor tør mange børn læse mere, end de plejer, siger bibliotekaren.' Hvorfor tør børnene læse mere, når Balder er der?","o":["Fordi Balder hverken retter dem eller griner af dem","Fordi bibliotekaren giver dem en præmie bagefter","Fordi Balder kun kommer på biblioteket om onsdagen","Fordi hunden selv vælger de letteste bøger til dem"],"a":"Fordi Balder hverken retter dem eller griner af dem","r":"Ordet 'derfor' binder årsag og virkning sammen: Hunden retter ikke og griner ikke, og så tør børnene mere."},
{"l":2905,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Den gamle kone gav Karla en magisk nøgle, så hun kunne åbne troldens port.' Hvilken rolle har den gamle kone?","o":["modstander","hjælper","hovedperson","fortæller"],"a":"hjælper","r":"En hjælper støtter hovedpersonen på vejen, tit med en gave eller et godt råd. Trolden er modstanderen."},
{"l":2926,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et talord: 'Der står tolv stole i lokalet.'","o":["stole","står","tolv","lokalet"],"a":"tolv","r":"'Tolv' fortæller, hvor mange stole der er. Ord, der angiver antal eller rækkefølge, er talord."},
{"l":2948,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Vil du ___ tæppet på sofaen?'","o":["ligge","lægger","læge","lægge"],"a":"lægge","r":"Du flytter noget, nemlig tæppet, hen på sofaen. Efter 'vil' står navnemåden."},
{"l":2970,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Naboen ___ sin gamle cykel på nettet.'","o":["sælger","sælge","sæljer","sælgerer"],"a":"sælger","r":"Ordet staves med lg og får nutids-r. G'et høres som et j, men det skrives med g."},
{"l":2987,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør 'løvfældende' træer om efteråret?","o":["De får nye grønne nåle","De taber deres blade","De mister deres rødder","De sætter blomster i toppen"],"a":"De taber deres blade","r":"Løv er et andet ord for blade, og at fælde betyder her at tabe. Bøg og eg er løvfældende træer."},
{"l":3006,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lyn og torden sker på samme tid. Alligevel ser man lynet først, for lys bevæger sig meget hurtigere end lyd. Hvis der går lang tid, fra du ser lynet, til du hører tordenen, er uvejret langt væk.' Hvad kan du slutte, hvis tordenen kommer lige efter lynet?","o":["At lynet slog ned for længe siden","At lyden er blevet hurtigere end lyset","At uvejret er tæt på dig","At uvejret snart er ovre"],"a":"At uvejret er tæt på dig","r":"Lang tid betyder langt væk. Så må kort tid betyde, at uvejret er tæt på."},
{"l":3025,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mener man, når man efter en lang ferie siger: 'Ude godt, men hjemme bedst'?","o":["Det er dejligst at være ude i naturen","Det er for koldt at rejse om vinteren","Det er for dyrt at tage på ferie","Det er dejligt at komme hjem igen"],"a":"Det er dejligt at komme hjem igen","r":"Det kan være dejligt at være ude at rejse, men ordsproget siger, at intet slår ens eget hjem."},
{"l":3047,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan stå i stedet for 'ledsagede' her: 'Mor ledsagede bedstefar til lægen.'","o":["fulgte","sendte","mindede","skubbede"],"a":"fulgte","r":"At ledsage nogen er at følge med dem. Mor gik altså sammen med bedstefar hele vejen."},
{"l":3069,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bier fortæller hinanden, hvor der er mad. Når en bi har fundet blomster, vender den hjem og laver en særlig dans i boet. Dansens retning og længde viser de andre bier, hvor de skal flyve hen. Sådan kan hele boet hurtigt finde føden.' Hvad bruger bierne dansen til?","o":["At holde sig varme i boet","At vise vej til føden","At jage fremmede bier væk","At vælge en ny dronning"],"a":"At vise vej til føden","r":"Dansen viser retning og afstand, så de andre bier kan finde blomsterne."},
{"l":3085,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Efter det voldsomme regnvejr stod vandet højt i gaderne. Der var ___ i hele byen.'","o":["tørke","jordskælv","oversvømmelse","snestorm"],"a":"oversvømmelse","r":"Når vandet stiger og dækker veje og huse, kaldes det en oversvømmelse. Tørke er det modsatte: for lidt vand."},
{"l":3105,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mikkel og Aya gik den samme vej hjem hver dag. I dag gik Aya på den anden side af vejen med blikket i jorden. Mikkel råbte hej, men hun svarede ikke. Han tænkte på det, han havde sagt i frikvarteret, og mærkede en klump i maven.' Hvad kan man forstå af teksten?","o":["Aya har ikke hørt, at Mikkel råbte hej","Aya skal besøge nogen i en anden retning","Mikkel har mavepine og burde gå til lægen","Mikkel frygter, at han har såret Aya"],"a":"Mikkel frygter, at han har såret Aya","r":"Klumpen i maven og tanken på det, han sagde, viser, at han er bange for at have såret hende."},
{"l":3124,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find grundleddet: 'I skolegården leger børnene fangeleg.'","o":["børnene","I skolegården","leger","fangeleg"],"a":"børnene","r":"Spørg: Hvem leger? Det gør børnene, selv om de ikke står først i sætningen."},
{"l":3146,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilke ord udgør udsagnsleddet: 'Lærke har tegnet en hest.'","o":["Lærke","har tegnet","en hest","Lærke har"],"a":"har tegnet","r":"I førnutid består udsagnsleddet af to ord: 'har' og tillægsformen 'tegnet'."},
{"l":3168,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find genstandsleddet: 'Zainab spiser en banan.'","o":["Zainab","spiser","en banan","Zainab spiser"],"a":"en banan","r":"Spørg: Hvad spiser Zainab? Svaret 'en banan' er genstandsleddet, altså det, handlingen går ud over."},
{"l":3188,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om sommerferien har alle kommaer rigtigt?","o":["Vi bader griller, spiller kort, og læser bøger.","Vi, bader griller spiller kort og læser bøger.","Vi bader, griller spiller, kort og læser bøger.","Vi bader, griller, spiller kort og læser bøger."],"a":"Vi bader, griller, spiller kort og læser bøger.","r":"Opremsningen har fire dele. 'spiller kort' er én del, så kommaet må ikke stå midt i den."},
{"l":3207,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: 'I Paris mødte Sara en Franskmand fra Lyon.'?","o":["Franskmand","Paris","Sara","Lyon"],"a":"Franskmand","r":"Ord for folk fra et land skrives med lille, så det hedder 'franskmand'. De andre ord er navne."},
{"l":3226,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Hvis du øver dig hver dag bliver du bedre til at spille klaver.'?","o":["øver","dag","bliver","bedre"],"a":"dag","r":"'hver dag' hører med til ledsætningen. Hovedsætningen begynder først med 'bliver'."},
{"l":3245,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket bindeord giver mening: 'Hun ville gerne med, ___ hun havde ikke tid.'","o":["så","fordi","men","eller"],"a":"men","r":"De to dele står i modsætning til hinanden: Hun vil gerne, men kan ikke. Modsætning viser man med 'men'."},
{"l":3265,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mangler her: 'Alle i klassen hjalp hinanden på lejrturen. Der var et fint ___.'","o":["skænderi","uheld","forbud","sammenhold"],"a":"sammenhold","r":"Sammenhold er, når en gruppe støtter hinanden og står sammen. Det passer på en klasse, der hjælper hinanden."},
{"l":3287,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvordan har man det, når man er 'skuffet'?","o":["Man er ked af, at noget ikke blev, som man håbede","Man er glad for, at noget gik bedre end ventet","Man er bange for, at der sker noget farligt","Man er træt, fordi man har arbejdet hele dagen"],"a":"Man er ked af, at noget ikke blev, som man håbede","r":"Skuffelse kommer, når noget ikke lever op til det, man havde glædet sig til."},
{"l":3302,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om stranden skal ikke have komma?","o":["Da vi havde badet spiste vi på stranden.","Efter badet spiste vi på stranden.","Når vi har badet spiser vi på stranden.","Fordi vi havde badet spiste vi på stranden."],"a":"Efter badet spiste vi på stranden.","r":"'Efter badet' har intet udsagnsord og er ikke en ledsætning. De tre andre begynder med en ledsætning og skal have komma."},
{"l":3322,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Mia skynder ___ hen til bussen.'","o":["hende","hun","sig","hendes"],"a":"sig","r":"Mia skynder på sig selv. Når et stedord peger tilbage på grundleddet i tredje person, hedder det 'sig'."}
